1	/* ReSpec slide layouts, 16:9 at 1920x1080. Import after ../tokens/tokens.css.
2	   Why plain CSS: opens in any browser and prints to PDF without a build step. */
3	@page { size: 1920px 1080px; margin: 0; }
4	* { box-sizing: border-box; margin: 0; padding: 0; }
5	html, body { background: #d9d9d9; font-family: var(--font-sans); color: var(--ink); -webkit-print-color-adjust: exact; print-color-adjust: exact; }
6	@media print { html, body { background: none; } .slide { margin: 0 !important; } }
7	
8	/* Frame: every slide has the same top bar, three-stripe accent and footer. */
9	.slide { width: 1920px; height: 1080px; position: relative; overflow: hidden; background: var(--white); margin: 0 auto 40px; break-after: page; }
10	.slide .top { position: absolute; left: 120px; right: 120px; top: 64px; display: flex; justify-content: space-between; align-items: center; }
11	.slide .top img { height: 40px; }
12	.eyebrow { font-size: 22px; font-weight: 600; text-transform: uppercase; color: var(--grey-500); }
13	.stripes { position: absolute; left: 0; right: 0; top: 140px; height: 4px; display: grid; grid-template-columns: 1fr 1fr 1fr; }
14	.stripes i:nth-child(1) { background: var(--m-light); }
15	.stripes i:nth-child(2) { background: var(--m-dark); }
16	.stripes i:nth-child(3) { background: var(--m-red); }
17	.foot { position: absolute; left: 120px; right: 120px; bottom: 48px; display: flex; justify-content: space-between; font-size: 18px; color: var(--grey-500); border-top: 1px solid var(--hairline); padding-top: 16px; }
18	.body { position: absolute; left: 120px; right: 120px; top: 210px; bottom: 120px; }
19	
20	/* Type scale */
21	.display { font-size: 200px; font-weight: 300; line-height: 1; }
22	h1 { font-size: 84px; font-weight: 300; line-height: 1.05; }
23	h2 { font-size: 64px; font-weight: 400; line-height: 1.1; max-width: 1500px; }
24	h3 { font-size: 30px; font-weight: 600; margin-bottom: 12px; }
25	p, li { font-size: 28px; line-height: 1.45; }
26	.lead { font-size: 40px; font-weight: 300; line-height: 1.35; }
27	.muted { color: var(--grey-500); }
28	.blue { color: var(--blue); }
29	
30	/* Building blocks */
31	.tag { display: inline-block; font-size: 20px; font-weight: 600; text-transform: uppercase; color: var(--blue); border: 1.5px solid var(--blue); padding: 6px 14px; margin-bottom: 28px; }
32	.card { border: 1px solid var(--hairline); padding: 36px; background: var(--white); }
33	.card.tint { background: var(--grey-100); border-color: var(--grey-100); }
34	.card.accent { border-color: var(--blue); }
35	.card.note { border-left: 6px solid var(--role-human); }
36	.shot { width: 100%; border: 1px solid var(--hairline); display: block; }
37	.num { font-size: 120px; font-weight: 300; line-height: 1; }
38	.num small { font-size: 48px; }
39	.label { font-size: 22px; font-weight: 600; text-transform: uppercase; color: var(--grey-500); margin-top: 12px; }
40	.btn { display: inline-block; background: var(--blue); color: #fff; font-size: 24px; font-weight: 500; padding: 20px 36px; }
41	.quote { font-size: 56px; font-weight: 300; line-height: 1.25; border-left: 6px solid var(--blue); padding-left: 48px; }
42	.lvl { display: inline-block; width: 44px; height: 44px; color: #fff; font-weight: 600; text-align: center; line-height: 44px; font-size: 24px; margin-right: 16px; }
43	.role { display: inline-block; width: 22px; height: 22px; margin-right: 12px; vertical-align: -2px; }
44	.placeholder { background: repeating-linear-gradient(45deg, var(--grey-100), var(--grey-100) 16px, #ececec 16px, #ececec 32px); border: 1px dashed #c4c4c4; display: flex; align-items: center; justify-content: center; color: var(--grey-500); font-size: 24px; }
45	
46	/* Grids */
47	.grid2 { display: grid; grid-template-columns: 1fr 1fr; gap: 64px; }
48	.grid3 { display: grid; grid-template-columns: repeat(3, 1fr); gap: 40px; }
49	.grid4 { display: grid; grid-template-columns: repeat(4, 1fr); gap: 32px; }
50	.flow { display: grid; grid-template-columns: 1fr 80px 1fr 80px 1fr; align-items: center; }
51	.flow .arrow { font-size: 56px; color: var(--blue); text-align: center; }
52	
53	/* Dark slides (title, section, closing) over a photo */
54	.dark { background: var(--black); color: var(--white); }
55	.dark .muted, .dark .foot, .dark .eyebrow { color: #a8a8a8; }
56	.dark .foot { border-color: #2a2a2a; }
57	.photo { position: absolute; inset: 0; background-size: cover; background-position: center; }
58	.shade { position: absolute; inset: 0; background: linear-gradient(90deg, rgba(10,10,11,.92) 0%, rgba(10,10,11,.55) 50%, rgba(10,10,11,.1) 100%); }
59

