  .diagram-img { width: 100%; height: 520px; object-fit: contain; background: var(--white); border: 1px solid var(--hairline); }
  /* Jede Folie ist fest 1920px breit (fuer den PDF-Export). Im Browser auf die Fensterbreite
     herunterskalieren, damit nichts seitlich abgeschnitten wird oder gescrollt werden muss.
     Beim Drucken (PDF) nicht aktiv, damit der Export weiter volle Auflösung hat. */
  @media screen {
    .slide { zoom: calc(100vw / 1920px); }
  }
</style>
